    int B = x.size(0);
    int R = x.size(1);
    int K = x.size(2);

    auto output = torch::empty({B, K}, x.options());

    const int BLOCK = 256;
    dim3 grid((K + BLOCK - 1) / BLOCK, B);
    dim3 block(BLOCK);

    mean_dim1_kernel<<<grid, block>>>(
