#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// Dual-output strip-mined kernel: each thread handles two adjacent output columns.
// Grid: (ceil(K / (BLOCK*2)), B), Block: BLOCK=256
// Thread t in block handles columns k0 = blockIdx.x*(BLOCK*2)+t and k1 = k0+BLOCK.

