    int k1 = k0 + BLOCK;
    int b  = blockIdx.y;
    if (b >= B) return;

    const float* base = input + (long long)b * R * K;
    float sum0 = 0.0f;
    float sum1 = 0.0f;

    bool valid0 = (k0 < K);
    bool valid1 = (k1 < K);

    if (valid0 && valid1) {
        #pragma unroll 4
        for (int r = 0; r < R; r++) {
            long long off = (long long)r * K;
            sum0 += __ldg(base + off + k0);
            sum1 += __ldg(base + off + k1);
        }
    } else if (valid0) {
        #pragma unroll 4
        for (int r = 0; r < R; r++) {
            sum0 += __ldg(base + (long long)r * K + k0);
        }
